SELECT EXISTS (
SELECT 1 FROM guard_senior
WHERE guard_id = #{guardId}
AND senior_id = #{seniorId}
AND status = 'ACTIVE'
)

SELECT EXISTS (
SELECT 1 FROM guard_senior
WHERE senior_id = #{wardId}
AND status = 'ACTIVE'
)

SELECT relation_id, guard_id, senior_id AS ward_id, status, connected_at
FROM guard_senior
WHERE guard_id = #{guardId}
AND senior_id = #{wardId}
